<?php $page_title='Order details'; require 'includes/header.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT o.*,COALESCE(o.guest_name,u.name,'Guest') customer,COALESCE(o.guest_email,u.email) email FROM orders o LEFT JOIN users u ON u.id=o.user_id WHERE o.id=?");$s->execute([$id]);$o=$s->fetch();if(!$o){echo '<div class="notice error">Order not found.</div>';require 'includes/footer.php';exit;}$s=$pdo->prepare("SELECT oi.*,p.name,p.image FROM order_items oi LEFT JOIN products p ON p.id=oi.product_id WHERE oi.order_id=?");$s->execute([$id]);$items=$s->fetchAll();?><div class="card"><h2>Order #<?=intval($o['id'])?></h2><p><b>Customer:</b> <?=admin_h($o['customer'])?> · <?=admin_h($o['email']??'')?></p><p><b>Phone:</b> <?=admin_h($o['guest_phone']??'')?> · <b>Address:</b> <?=admin_h($o['address']??'')?></p><p><b>Status:</b> <span class="pill"><?=admin_h($o['status'])?></span></p><div class="table-wrap"><table class="table"><tr><th>Product</th><th>Qty</th><th>Unit price</th><th>Subtotal</th></tr><?php foreach($items as $i):?><tr><td><?=admin_h($i['name']??'Deleted product')?></td><td><?=intval($i['quantity'])?></td><td><?=CURRENCY.number_format($i['unit_price'],2)?></td><td><?=CURRENCY.number_format($i['unit_price']*$i['quantity'],2)?></td></tr><?php endforeach;?></table></div><h2>Total: <?=CURRENCY.number_format($o['total'],2)?></h2></div><?php require 'includes/footer.php';
